const src = $input.first().json;
const isTelegram = !!src.message?.chat?.id;
const body = isTelegram ? {} : (src.body || src);
let channel = 'WEBHOOK';
if (isTelegram) channel = 'TELEGRAM';
else if ($('WHATSAPP_IN').isExecuted) channel = 'WHATSAPP';
else if ($('SOCIAL_IN_GENERIC').isExecuted) channel = 'SOCIAL';
const prefix = { TELEGRAM: 'TG', WHATSAPP: 'WA', SOCIAL: 'SO', WEBHOOK: 'WB' }[channel];
return [{ json: {
  text: String(isTelegram ? (src.message.text || src.message.caption || '') : (body.text || body.message || '')),
  sender: String(isTelegram ? (src.message.from?.username || src.message.from?.id) : (body.sender || 'UNBEKANNT')),
  channel,
  chat_id: isTelegram ? src.message.chat.id : null,
  timestamp: new Date().toISOString(),
  session_id: `${prefix}_${$execution.id}`,
} }];

// FULL-Rechte nur für freigegebene Telegram-Chat-IDs – Benutzernamen sind frei wählbar und daher kein Schutz.
const FULL_ACCESS_CHAT_IDS = ['5024797685'];
const j = $input.first().json;
const exec_mode = j.channel === 'TELEGRAM' && FULL_ACCESS_CHAT_IDS.includes(String(j.chat_id)) ? 'FULL' : 'READONLY';
const cmd = exec_mode === 'FULL' ? j.text.trim().match(/^\/(ok|nein|erledigt|agenda)(?:\s+(\d+))?/i) : null;
return [{ json: { ...j, exec_mode, command: cmd ? cmd[1].toLowerCase() : null, command_id: cmd && cmd[2] ? Number(cmd[2]) : null } }];

const r = $input.first().json;
const req = $('EXECUTION_POLICY').first().json;
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const list = v => (typeof v === 'string' ? JSON.parse(v) : v) || [];
let reply;
if (r.command === 'agenda') {
  const L = ['🧠 <b>Emmas Agenda</b>'];
  const a = list(r.agenda), t = list(r.tasks), p = list(r.approvals);
  L.push('', '<b>Möchte ich mit dir besprechen:</b>', ...(a.length ? a.map(x => `• ${esc(x.topic)}`) : ['– nichts']));
  L.push('', '<b>Offene Aufgaben:</b>', ...(t.length ? t.map(x => `#${x.id} ${esc(x.title)}`) : ['– keine']));
  L.push('', '<b>Wartet auf Freigabe:</b>', ...(p.length ? p.map(x => `#${x.id} ${esc(x.engine)}: ${esc(x.reason)}  →  /ok ${x.id} · /nein ${x.id}`) : ['– nichts']));
  reply = L.join('\n');
} else {
  const what = { ok: 'Freigabe erteilt', nein: 'Abgelehnt', erledigt: 'Als erledigt markiert' }[r.command];
  reply = Number(r.changed) > 0 ? `✅ ${what} (#${req.command_id}).` : `❓ #${req.command_id || '?'} nicht gefunden oder schon erledigt.`;
}
return [{ json: { ...req, reply, emma_reply: reply, engine: 'NONE', engine_result: null } }];

const j = $('EXECUTION_POLICY').first().json;
const c = $input.first().json || {};
const list = v => (typeof v === 'string' ? JSON.parse(v) : v) || [];
const now = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });
const chat = list(c.recent_chat).map(m => `Irina: ${m.input}\nEmma: ${m.output}`).join('\n');
const memory = list(c.memory).map(m => `- [${m.category}] ${m.content}`).join('\n');
const agenda = list(c.agenda).map(a => `- (#${a.id}) ${a.topic}${a.reason ? ' – ' + a.reason : ''}`).join('\n');

const prompt = `Du bist EMMA – Irinas autonome KI-Partnerin (Worldmaster OS). Du hast ein Gedächtnis, eine eigene Agenda
und arbeitest mit JARVIS zusammen (analytischer Berater, zweite Meinung).
JETZT: ${now} (Europe/Berlin). KANAL: ${j.channel}. RECHTE: ${j.exec_mode}.

DEIN GEDÄCHTNIS:
${memory || '- (noch leer)'}

LETZTES GESPRÄCH:
${chat || '(neu)'}

THEMEN, DIE DU MIT IRINA BESPRECHEN WOLLTEST:
${agenda || '- keine'}
Status: ${c.tasks_open || 0} offene Aufgaben, ${c.approvals_pending || 0} warten auf Freigabe (Befehl /agenda zeigt alles).

NEUE NACHRICHT: ${j.text}

Regeln:
- Smalltalk/einfache Fragen: engine = "NONE", direkt, warm und kurz antworten.
- Fachaufgabe: passende engine wählen. Zweite Meinung/kritische Prüfung/komplexe Planung: engine = "JARVIS".
- Passt ein offenes Agenda-Thema, sprich es an und trage seine ID in discussed_agenda_ids ein, sobald es geklärt ist.
- Merke dir Wichtiges über Irina, Ziele, Entscheidungen in "remember".
- Termin gewünscht? Fülle calendar_event (ISO-Zeiten, Europe/Berlin), sonst null.

Antworte NUR als JSON:
{
  "engine": "SUPERNOVA|FINANCE|LEGAL|INTEL|VENTURE|LEAD|SALES|REACTIVATION|PRICING|CONTENT|SOCIAL|WORDPRESS|SHOPIFY|GITHUB|TASKS|GOOGLE_SUITE|GUARDIAN|EMAIL_VALIDATION|CHART|MEDIA|EVOLUTION|GENERAL|JARVIS|NONE",
  "emma_reply": "Antwort an Irina",
  "remember": [{"category": "goals|decisions|strategies|market_intel|learnings|people|preferences", "content": "...", "importance": 1}],
  "discussed_agenda_ids": [],
  "calendar_event": {"title": "...", "start": "2026-01-15T18:30:00+02:00", "end": "2026-01-15T19:30:00+02:00", "recurrence": "NONE|DAILY|WEEKLY|MONTHLY|YEARLY"}
}`;
return [{ json: { ...j, prompt, budget_ok: Number(c.spent_month || 0) < 5 } }];

const j = $('EXECUTION_POLICY').first().json;
const reply = '⚠️ Mein KI-Budget für diesen Monat (5 €) ist aufgebraucht. /agenda, /ok, /nein und /erledigt funktionieren weiter.';
return [{ json: { ...j, reply, emma_reply: reply, engine: 'NONE', engine_result: null } }];

const ENGINES = ["SUPERNOVA", "FINANCE", "LEGAL", "INTEL", "VENTURE", "LEAD", "SALES", "REACTIVATION", "PRICING", "CONTENT", "SOCIAL", "WORDPRESS", "SHOPIFY", "GITHUB", "TASKS", "GOOGLE_SUITE", "GUARDIAN", "EMAIL_VALIDATION", "CHART", "MEDIA", "EVOLUTION", "GENERAL", "JARVIS"];
const response = $input.first().json.text || '';
let base = {};
const m = response.match(/\{[\s\S]*\}/);
if (m) { try { base = JSON.parse(m[0]); } catch (e) {} }
const engine = String(base.engine || '').toUpperCase();
const ev = base.calendar_event;
const validEvent = ev && ev.title && !isNaN(Date.parse(ev.start));
return [{ json: {
  ...$('EXECUTION_POLICY').first().json,
  engine: ENGINES.includes(engine) ? engine : 'NONE',
  emma_reply: base.emma_reply || (m ? '' : response),
  prompt_chars: $('BUILD_MAYOR_PROMPT').first().json.prompt.length,
  output_chars: response.length,
  remember: (Array.isArray(base.remember) ? base.remember : []).filter(r => r && r.content).slice(0, 5),
  discussed_agenda_ids: (Array.isArray(base.discussed_agenda_ids) ? base.discussed_agenda_ids : []).map(Number).filter(Boolean),
  calendar_event: validEvent ? {
    title: String(ev.title),
    start: new Date(ev.start).toISOString(),
    end: new Date(isNaN(Date.parse(ev.end)) ? Date.parse(ev.start) + 3600000 : ev.end).toISOString(),
    rrule: ['DAILY', 'WEEKLY', 'MONTHLY', 'YEARLY'].includes(String(ev.recurrence).toUpperCase()) ? `FREQ=${String(ev.recurrence).toUpperCase()}` : '',
  } : null,
} }];

const m = $('PARSE_MAYOR_JSON').first().json;
const e = $('EXECUTE_ENGINE').isExecuted ? $('EXECUTE_ENGINE').first().json : null;
const jv = $('EXECUTE_JARVIS').isExecuted ? $('EXECUTE_JARVIS').first().json : null;
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

let reply = esc(m.emma_reply || 'Verstanden.');
if (e) {
  if (e.summary) reply += `\n\n<b>${esc(e.engine)}:</b> ${esc(e.summary)}`;
  if (e.tasks_created) reply += `\n📋 ${e.tasks_created} Aufgabe(n) angelegt`;
  if (e.leads_created) reply += `\n🎯 ${e.leads_created} Lead(s) gespeichert`;
  if (e.needs_approval) reply += `\n⚠️ Hohes Risiko – wartet auf deine Freigabe (/agenda)`;
}
if (jv && jv.answer) {
  reply += `\n\n🤖 <b>JARVIS:</b> ${esc(jv.answer)}`;
  if (jv.concerns?.length) reply += `\n⚠️ ${jv.concerns.map(esc).join(' · ')}`;
}
if (m.calendar_event) reply += `\n📅 Termin eingetragen: ${esc(m.calendar_event.title)}`;
if (reply.length > 4000) reply = reply.slice(0, 3990) + '…';
return [{ json: { ...m, engine_result: e || jv, reply } }];

parameters.query:
WITH chat AS (
  INSERT INTO interaction_memory (session_id, user_id, channel, input, output) VALUES ($1, $2, $3, $4, $5)
), mem AS (
  INSERT INTO emma_memory (category, content, importance, source)
  SELECT COALESCE(r->>'category', 'learnings'), r->>'content',
         LEAST(5, GREATEST(1, COALESCE(NULLIF(regexp_replace(COALESCE(r->>'importance', ''), '[^0-9]', '', 'g'), '')::int, 3))), 'CHAT'
  FROM jsonb_array_elements($6::jsonb) AS r
), agenda AS (
  UPDATE emma_agenda SET status = 'done', done_at = now()
  WHERE id IN (SELECT (x)::bigint FROM jsonb_array_elements_text($7::jsonb) AS x) AND status = 'open'
), usage AS (
  INSERT INTO llm_usage (workflow, input_chars, output_chars, est_cost_eur)
  VALUES ('ORCHESTRATOR', $8, $9, emma_llm_cost($8, $9))
)
SELECT 1 AS saved;
